/** Myers-Diff für Zeilen sowie begrenzte Inline-Word-Diffs. */
import type { DiffHunk, DiffLine, InlineSegment } from "./types.ts";

type EditOp = "keep" | "insert" | "delete";

const MAX_LINES = 10_000;
// Myers ist O((N+M)*D) mit D = Edit-Distanz, nicht mit der Dateigröße selbst
// teuer — bei kleinen, lokalisierten Änderungen ist D klein, auch in langen
// Dateien. Die alten Werte (50_000 Bytes / 4_000 Zeilen) lagen unter der
// Größe gewöhnlicher Quelldateien dieses Repos (z. B. tool-renderers.ts,
// index.ts, tests/suites/runtime/aurora-ui.mjs) und ließen den Fallback
// dadurch bei praktisch jeder Bearbeitung dieser Dateien greifen: Statt
// eines echten Diffs zeigte die Ansicht "ganze Datei gelöscht + neu
// eingefügt". Die neuen Grenzwerte decken die realen Dateigrößen dieses
// Repos mit deutlichem Puffer ab und bleiben trotzdem klein genug, um ein
// pathologisches Worst-Case (komplett verschiedene Dateien) nicht spürbar
// zu verlangsamen.
const MAX_BYTES = 500_000;
const MAX_MYERS_LENGTH = 20_000;
const MAX_INLINE_TOKENS = 512;
const MAX_INLINE_MATRIX_CELLS = 65_536;

export function computeLineDiff(
  oldLines: string[],
  newLines: string[],
): EditOp[] {
  const size = oldLines.join("\n").length + newLines.join("\n").length;
  if (
    oldLines.length > MAX_LINES ||
    newLines.length > MAX_LINES ||
    oldLines.length + newLines.length > MAX_MYERS_LENGTH ||
    size > MAX_BYTES
  ) {
    return [
      ...oldLines.map(() => "delete" as const),
      ...newLines.map(() => "insert" as const),
    ];
  }
  return myers(oldLines, newLines);
}

function myers(a: string[], b: string[]): EditOp[] {
  const max = a.length + b.length;
  const trace: Array<Map<number, number>> = [];
  const v = new Map<number, number>([[1, 0]]);

  for (let d = 0; d <= max; d++) {
    // Snapshot des vorherigen D-Schritts für die Rückwärtsrekonstruktion.
    trace.push(new Map(v));
    for (let k = -d; k <= d; k += 2) {
      const down =
        k === -d || (k !== d && (v.get(k - 1) ?? -1) < (v.get(k + 1) ?? -1));
      let x = down ? (v.get(k + 1) ?? 0) : (v.get(k - 1) ?? 0) + 1;
      let y = x - k;
      while (x < a.length && y < b.length && a[x] === b[y]) {
        x++;
        y++;
      }
      v.set(k, x);
      if (x >= a.length && y >= b.length) return reconstruct(a, b, trace);
    }
  }
  return [...a.map(() => "delete" as const), ...b.map(() => "insert" as const)];
}

function reconstruct(
  a: string[],
  b: string[],
  trace: Array<Map<number, number>>,
): EditOp[] {
  const reversed: EditOp[] = [];
  let x = a.length;
  let y = b.length;
  for (let d = trace.length - 1; d > 0; d--) {
    const v = trace[d]!;
    const k = x - y;
    const down =
      k === -d || (k !== d && (v.get(k - 1) ?? -1) < (v.get(k + 1) ?? -1));
    const previousK = down ? k + 1 : k - 1;
    const previousX = v.get(previousK) ?? 0;
    const previousY = previousX - previousK;
    while (x > previousX && y > previousY) {
      reversed.push("keep");
      x--;
      y--;
    }
    reversed.push(down ? "insert" : "delete");
    if (down) y--;
    else x--;
  }
  while (x > 0 && y > 0) {
    reversed.push("keep");
    x--;
    y--;
  }
  while (x-- > 0) reversed.push("delete");
  while (y-- > 0) reversed.push("insert");
  return reversed.reverse();
}

interface ScriptStep {
  op: EditOp;
  oldLine?: number;
  newLine?: number;
  text: string;
}

/** Konvertiert ein Edit-Script in getrennte Unified-Diff-Hunks. */
export function scriptToHunks(
  oldLines: string[],
  newLines: string[],
  script: EditOp[],
  contextLines = 3,
): DiffHunk[] {
  const steps = buildSteps(oldLines, newLines, script);
  const changed = steps.flatMap((step, index) =>
    step.op === "keep" ? [] : [index],
  );
  if (changed.length === 0) return [];

  const ranges: Array<[number, number]> = [];
  let first = changed[0]!;
  let last = first;
  for (const index of changed.slice(1)) {
    // Context überlappt nur, wenn zwischen den Änderungen höchstens 2*context Zeilen liegen.
    if (index - last <= contextLines * 2 + 1) {
      last = index;
    } else {
      ranges.push([
        Math.max(0, first - contextLines),
        Math.min(steps.length - 1, last + contextLines),
      ]);
      first = index;
      last = index;
    }
  }
  ranges.push([
    Math.max(0, first - contextLines),
    Math.min(steps.length - 1, last + contextLines),
  ]);

  return ranges.map(([start, end]) => {
    const selected = steps.slice(start, end + 1);
    const lines: DiffLine[] = selected.map((step) => {
      if (step.op === "keep") {
        return {
          kind: "context",
          oldLine: step.oldLine,
          newLine: step.newLine,
          text: step.text,
        };
      }
      if (step.op === "delete") {
        return { kind: "removed", oldLine: step.oldLine, text: step.text };
      }
      return { kind: "added", newLine: step.newLine, text: step.text };
    });
    applyInlineHighlights(lines);
    return {
      oldStart:
        selected.find((step) => step.oldLine !== undefined)?.oldLine ?? 0,
      oldCount: lines.filter((line) => line.kind !== "added").length,
      newStart:
        selected.find((step) => step.newLine !== undefined)?.newLine ?? 0,
      newCount: lines.filter((line) => line.kind !== "removed").length,
      lines,
    };
  });
}

function buildSteps(
  oldLines: string[],
  newLines: string[],
  script: EditOp[],
): ScriptStep[] {
  const steps: ScriptStep[] = [];
  let oldIndex = 0;
  let newIndex = 0;
  for (const op of script) {
    if (op === "keep") {
      steps.push({
        op,
        oldLine: oldIndex + 1,
        newLine: newIndex + 1,
        text: oldLines[oldIndex] ?? "",
      });
      oldIndex++;
      newIndex++;
    } else if (op === "delete") {
      steps.push({ op, oldLine: oldIndex + 1, text: oldLines[oldIndex] ?? "" });
      oldIndex++;
    } else {
      steps.push({ op, newLine: newIndex + 1, text: newLines[newIndex] ?? "" });
      newIndex++;
    }
  }
  return steps;
}

